<?php
declare(strict_types=1);
use Allfather\Loopia\Core\{Digest,Ids};
use Allfather\Loopia\Ingestion\{FetchResponse,FixedHostResolver,FixtureTransport};
use Allfather\Loopia\Product\P01\{Capture,SourceCards,Registry as P01Registry};
use Allfather\Loopia\Provider\{CredentialStore,FixtureModelTransport,ModelArtifactStore,ModelExecutor,ModelRegistration,ModelRequestBuilder,ModelResponse,OpenAIResponsesTransport,SecretBox};
use Allfather\Loopia\PromptOps\ProductPromptPack;
use Allfather\Loopia\Storage\EvidenceStore;
use Allfather\Loopia\Substrate\M01\Invocation;
use Allfather\Loopia\Substrate\M02\AccessGuard;
use Allfather\Loopia\Substrate\M03\Eligibility;
use Allfather\Loopia\Substrate\M04\Proposals;
use Allfather\Loopia\Substrate\M05\EvidenceSpine;
use Allfather\Loopia\Substrate\M06\Gateway;
use Allfather\Loopia\Tests\{Assert,Harness,Seed};
use Allfather\Loopia\Workflow\ContextEnvelope;

$db=Harness::freshDb();if($db===null){Assert::skip(Harness::unavailableReason());return;}
$clock=Harness::clock();$base=Seed::tenantWorkspace($db,$clock,'bounded-model');
$scope=$base+['actor_type'=>'OPERATOR','actor_id'=>$base['operator_id']];
$gateway=new Gateway($db,$clock,new AccessGuard($db,$clock),new Eligibility($db,$clock),new Invocation($db,$clock));
$evidence=new EvidenceSpine($db,$clock);$capture=new Capture($db,$clock,$gateway,$evidence);
$store=new EvidenceStore(sys_get_temp_dir().'/allfather-model-test-'.Ids::new());
$contextService=new ContextEnvelope($db,$clock,$store);$modelArtifacts=new ModelArtifactStore($db,$clock,$store);
(new \Allfather\Loopia\Product\P04\Distribution($db,$clock,new \Allfather\Loopia\Substrate\M10\DecisionLedger($db,$clock)))->configureRoleRedactionPolicy(['tenant_id'=>$scope['tenant_id'],'workspace_id'=>$scope['workspace_id'],'target_org_role'=>'SALES','redaction_rules'=>[]]);
$credentialStore=new CredentialStore($db,$clock,SecretBox::fromMasterKey(base64_encode(random_bytes(32))));
$registration=new ModelRegistration($db,$clock);
Assert::same('MODEL_REGISTRATION_DENIED',$registration->ensure($scope)->reasonCode(),'descriptor setup has no implicit authority');
Assert::same('PROVIDER_CREDENTIAL_MANAGEMENT_DENIED',$credentialStore->save($scope,'fixture-secret-only')->reasonCode(),'credential setup has no implicit authority');
$role=Seed::role($db,$clock,'monitor-fixture-operator',['tool.invoke','evidence.read','tenant.administer','runtime_host_binding.administer']);
Seed::membership($db,$clock,$scope['tenant_id'],$scope['workspace_id'],$scope['operator_id'],$role['role_id']);
$read=Seed::governedToolChain($db,$clock,$scope);
$modelRegistration=$registration->ensure($scope);
Assert::true($modelRegistration->isOk(),'scoped setup registers exact model descriptor');
if(!$modelRegistration->isOk()){Assert::same(null,$modelRegistration->reasonCode(),'registration reason');return;}
$model=$modelRegistration->value();
Assert::same($model,$registration->ensure($scope)->value(),'repeated descriptor setup reuses exact identity');
Assert::same(false,$model['model_activation_granted'],'registration grants no activation');
Assert::same(0,(int)$db->scalar('SELECT COUNT(*) FROM tool_rights WHERE governed_tool_id=?',[$model['governed_tool_id']]),'registration grants no agent tool rights');
(new Eligibility($db,$clock))->grantToolRight($read['capability_contract_id'],$model['governed_tool_id'],[ModelRegistration::OPERATION_KEY],'INTERNAL_TRANSFORM','ANALYZE');
$assignment=(new Proposals($db,$clock))->assignToMission($read['mission_id'],$read['valkyrie_id'],$read['capability_contract_id'],'MODEL_INTERPRETER',[$model['governed_tool_id']],['ANALYZE'],$scope['operator_id']);
Assert::true($assignment->isOk(),'separate explicit mission assignment authorizes only model tool');
$card=(new SourceCards($db,$clock))->project(['tenant_id'=>$scope['tenant_id'],'source_name'=>'Synthetic source','source_url_safe'=>'https://sources.example/pricing','source_type'=>'website','allowed_use_class'=>'derived_summary_allowed','license_class'=>'PUBLIC_WEB_ALLOWED','customer_output_allowed'=>false,'derived_summary_allowed'=>true,'robots_policy_checked'=>true,'terms_policy_checked'=>true,'review_status'=>'approved','caching_policy'=>'standard_cache','retention_class'=>'standard']);
$p01=new P01Registry($db,$clock);
$competitor=$p01->registerCompetitor($scope['tenant_id'],$scope['workspace_id'],'Synthetic competitor','DIRECT','OPERATOR',$scope['operator_id'])->value()['competitor_id'];
$monitored=$p01->registerMonitoredSource($scope['tenant_id'],$scope['workspace_id'],$competitor,$card['source_ref_id'],$card['source_license_card_id'],'WEBSITE')->value()['monitored_source_id'];
$governance=array_intersect_key($read,array_flip(['mission_id','assignment_id','valkyrie_id','capability_contract_id','governed_tool_id','governed_tool_operation_id']))+['calling_actor_type'=>'OPERATOR','calling_actor_id'=>$scope['operator_id']];
$observations=[];$payloads=[];
foreach(['The planned seminar is November.','The planned seminar is December.'] as $i=>$body){
 if($i>0)$clock->advanceDays(1);
 $r=$capture->captureMonitoredSource(['tenant_id'=>$scope['tenant_id'],'workspace_id'=>$scope['workspace_id'],'monitored_source_id'=>$monitored,'capture_url'=>'https://sources.example/pricing','idempotency_key'=>'model-cap-'.$i,'correlation_id'=>Ids::new(),'governance'=>$governance],new FixtureTransport(['https://sources.example/pricing'=>new FetchResponse(200,'text/html',null,$body)]),new FixedHostResolver(['sources.example'=>['93.184.216.34']]));
 Assert::true($r->isOk(),'real governed fixture capture '.$i);
 if(!$r->isOk()){Assert::same(null,$r->reasonCode(),'capture refusal');return;}
 $eid=$db->scalar('SELECT evidence_id FROM source_snapshots WHERE source_snapshot_id=?',[$r->value()['source_snapshot_id']]);$observations[]=$eid;$payloads[$eid]=['url'=>'https://sources.example/pricing','body'=>$body];
}
$profileSource=$evidence->registerSource($scope['tenant_id'],$scope['workspace_id'],'UPLOADED_ARTIFACT','internal://owner/profile','INTERNAL_ANALYSIS','INTERNAL_DEMO','ACTIVE_FOR_CAPTURE');
$profileHash=$store->put('Owner-provided, unverified: we provide event studio services.')->value()['digest'];
$profile=$evidence->capture(['tenant_id'=>$scope['tenant_id'],'workspace_id'=>$scope['workspace_id'],'source_ref_id'=>$profileSource,'evidence_type'=>'UPLOADED_SOURCE_CAPTURE','captured_content_reference_safe'=>'evidence://'.$profileHash,'content_hash'=>$profileHash,'capture_method'=>'OWNER_UPLOAD','permitted_use_scope'=>'INTERNAL_ANALYSIS','sensitivity_class'=>'INTERNAL_DEMO']);
Assert::true($profile->isOk(),'profile captured through M05');if(!$profile->isOk())return;
$profileId=$profile->value()['evidence_id'];
$input=['mission_id'=>$read['mission_id'],'audience'=>'SALES','selected_target_org_role'=>'SALES','limits'=>['max_input_bytes'=>65536,'max_output_tokens'=>2048,'max_model_calls'=>4,'max_observation_age_seconds'=>86400],'profile_evidence_ids'=>[$profileId],'observation_evidence_ids'=>$observations,'source_ids'=>[$profileSource,$card['source_ref_id']],'observation_payloads'=>$payloads];
Assert::same('CONTEXT_SOURCE_OUTSIDE_MISSION',$contextService->prepare($scope,$input)->reasonCode(),'caller source selection cannot invent mission authority');
$db->run('UPDATE missions SET allowed_source_scope_ids=? WHERE mission_id=?',[json_encode($input['source_ids']),$read['mission_id']]);
$preparedContext=$contextService->prepare($scope,$input);
Assert::true($preparedContext->isOk(),'scoped current source and exact capture payloads prepare');
if(!$preparedContext->isOk()){Assert::same(null,$preparedContext->reasonCode(),'context reason');return;}
$context=$preparedContext->value();
Assert::same(['target_org_role'=>'SALES','redaction_profile'=>[]],$context['envelope']['routing_target'],'exact configured P04 target is bound independently of audience');
$unconfigured=$input;$unconfigured['selected_target_org_role']='MARKETING_CMO';
Assert::same('CONTEXT_ROUTING_TARGET_NOT_CONFIGURED',$contextService->prepare($scope,$unconfigured)->reasonCode(),'caller cannot invent a distribution target');
$missingTarget=$input;unset($missingTarget['selected_target_org_role']);
Assert::same('CONTEXT_ROUTING_TARGET_REQUIRED',$contextService->prepare($scope,$missingTarget)->reasonCode(),'generic audience never implies P04 target');
Assert::same('TENANT_PROVIDED',$context['envelope']['evidence'][0]['basis'],'profile is not independently verified');
Assert::same($payloads[$observations[0]]['body'],$context['envelope']['evidence'][1]['untrusted_text'],'actual captured bytes enter context');
Assert::true($contextService->revalidate($context)->isOk(),'unchanged context revalidates');
$single=$input;$single['observation_evidence_ids']=[$observations[0]];$single['observation_payloads']=[$observations[0]=>$payloads[$observations[0]]];
Assert::true($contextService->prepare($scope,$single)->isOk(),'baseline may validate one observation for authorized private retention');
$tampered=$input;$tampered['observation_payloads'][$observations[0]]['body']='invented';
Assert::same('CONTEXT_CAPTURE_CONTENT_MISMATCH',$contextService->prepare($scope,$tampered)->reasonCode(),'caller cannot substitute unobserved source prose');
$other=Seed::tenantWorkspace($db,$clock,'foreign-model');
Assert::same('CONTEXT_READ_NOT_AUTHORIZED',$contextService->prepare($other+['actor_type'=>'OPERATOR','actor_id'=>$other['operator_id']],$input)->reasonCode(),'foreign actor cannot compile context');
$db->run("UPDATE evidence_objects SET evidence_status='STALE_FOR_USE' WHERE evidence_id=?",[$observations[0]]);
Assert::same('CONTEXT_EVIDENCE_NOT_AVAILABLE',$contextService->revalidate($context)->reasonCode(),'stale lifecycle state blocks prepared context');
$db->run("UPDATE evidence_objects SET evidence_status='CAPTURED' WHERE evidence_id=?",[$observations[0]]);
$db->run("UPDATE source_license_cards SET caching_policy='no_cache' WHERE source_license_card_id=?",[$card['source_license_card_id']]);
Assert::same('CONTEXT_RETENTION_NOT_SUPPORTED',$contextService->revalidate($context)->reasonCode(),'current no-cache policy blocks retained model input');
$db->run("UPDATE source_license_cards SET caching_policy='standard_cache' WHERE source_license_card_id=?",[$card['source_license_card_id']]);
$db->run('UPDATE source_license_cards SET review_expires_at=? WHERE source_license_card_id=?',['2000-01-01T00:00:00.000Z',$card['source_license_card_id']]);
Assert::same('CONTEXT_SOURCE_POLICY_REFUSED',$contextService->revalidate($context)->reasonCode(),'expired current source review blocks');
$db->run('UPDATE source_license_cards SET review_expires_at=NULL WHERE source_license_card_id=?',[$card['source_license_card_id']]);
Assert::true($contextService->revalidate($context)->isOk(),'restored test policy matches again');

$prompt=ProductPromptPack::resolve('P01_SIGNAL_CLASSIFIER')->value();$request=ModelRequestBuilder::prepare($prompt,$context)->value();
$key='synthetic-key-never-network';$saved=$credentialStore->save($scope,$key);Assert::true($saved->isOk(),'private scoped credential setup seals fixture-only key');$credentialId=$saved->value()['provider_credential_id'];
Assert::false(str_contains(json_encode($saved->value()),$key),'credential response contains no plaintext');
Assert::false(str_contains(json_encode($db->one('SELECT * FROM provider_credentials WHERE provider_credential_id=?',[$credentialId])),$key),'stored credential is sealed');
Assert::same('PROVIDER_CREDENTIAL_NOT_AVAILABLE',$credentialStore->withCredential($other['tenant_id'],$credentialId,static fn($s)=>$s)->reasonCode(),'cross-tenant credential cannot open');
$sample=json_decode(file_get_contents(__DIR__.'/../fixtures/monitor_prompt_offline_cases.json'),true,128,JSON_THROW_ON_ERROR)['cases'][0]['candidate'];
$replace=['ev-before'=>$observations[0],'ev-after'=>$observations[1],'ev-profile'=>$profileId];$sample=json_decode(strtr(json_encode($sample),$replace),true);
$wire=static fn(array $candidate):string=>json_encode(['status'=>'completed','output'=>[['type'=>'message','content'=>[['type'=>'output_text','text'=>json_encode($candidate)]]]],'usage'=>['input_tokens'=>90,'output_tokens'=>40]]);
$transport=new FixtureModelTransport(static fn($r)=>new ModelResponse(200,$wire($sample),'req_fixture',null,1));
$executor=new ModelExecutor($db,$clock,$gateway,$credentialStore,$transport,$contextService,$modelArtifacts);
$command=['tenant_id'=>$scope['tenant_id'],'workspace_id'=>$scope['workspace_id'],'mission_id'=>$read['mission_id'],'assignment_id'=>$assignment->value()['assignment_id'],'valkyrie_id'=>$read['valkyrie_id'],'capability_contract_id'=>$read['capability_contract_id'],'governed_tool_id'=>$model['governed_tool_id'],'governed_tool_operation_id'=>$model['governed_tool_operation_id'],'requested_action_class'=>'ANALYZE','calling_actor_type'=>'OPERATOR','calling_actor_id'=>$scope['operator_id'],'idempotency_key'=>'model-one','correlation_id'=>Ids::new(),'required_entitlement_permission'=>'competition_monitoring.read'];
$native=new ModelExecutor($db,$clock,$gateway,$credentialStore,new OpenAIResponsesTransport(),$contextService,$modelArtifacts);
Assert::same('MODEL_PROMPT_INACTIVE',$native->execute($command,$request,$credentialId)['reason_code'],'native path remains inactive');
Assert::same(0,(int)$db->scalar('SELECT COUNT(*) FROM provider_model_attempts'),'inactive path consumed no attempt');
$result=$executor->execute($command,$request,$credentialId);
Assert::same('MODEL_CANDIDATE',$result['kind'],'M06/M01 authorized fixture transform produces candidate');
if($result['kind']!=='MODEL_CANDIDATE'){Assert::same(null,$result['reason_code'],'model reason');return;}
Assert::same(1,$transport->calls,'exactly one transport attempt');
Assert::same('FIXTURE',$result['execution_mode'],'fixture result is explicit');
Assert::same(true,$result['human_review_required'],'candidate grants no review or release');
Assert::same(0,(int)$db->scalar('SELECT evidence_capture_candidate FROM tool_execution_outcomes WHERE tool_request_id=?',[$result['dispatch']['tool_request_id']]),'model output cannot claim source evidence');
Assert::same(1,(int)$db->scalar('SELECT COUNT(*) FROM provider_model_results WHERE outcome=\'CANDIDATE\''),'append-only model result binds actual call');
Assert::same(1,(int)$db->scalar('SELECT COUNT(*) FROM provider_model_candidate_artifacts'),'validated candidate bytes are durable before workflow consumption');
$durable=$db->one('SELECT candidate_digest,artifact_digest FROM provider_model_candidate_artifacts LIMIT 1');
Assert::same($durable['candidate_digest'],$durable['artifact_digest'],'canonical candidate bytes share the provider candidate digest');
Assert::same('MODEL_REPLAY',$executor->execute($command,$request,$credentialId)['kind'],'same governed idempotency key replays receipt');
Assert::same(1,$transport->calls,'replay never invokes model again');
$metadata=json_encode($db->all('SELECT * FROM provider_model_attempts')).json_encode($db->all('SELECT * FROM provider_call_records'));
Assert::false(str_contains($metadata,$key),'telemetry contains no credential');
Assert::false(str_contains($metadata,$payloads[$observations[0]]['body']),'telemetry contains no source bodies');
foreach(['UPDATE provider_model_attempts SET execution_mode=\'LIVE\'','DELETE FROM provider_model_attempts','UPDATE provider_model_results SET outcome=\'REFUSED\'','DELETE FROM provider_model_results'] as $sql){try{$db->run($sql);Assert::fail('model provenance cannot mutate');}catch(PDOException){Assert::pass();}}

$credentialStore->revoke($scope,$credentialId);
$refused=$executor->execute([...$command,'idempotency_key'=>'model-no-key','correlation_id'=>Ids::new()],$request,$credentialId);
Assert::same('MODEL_CREDENTIAL_NOT_AVAILABLE',$refused['reason_code'],'revoked credential refuses after admission without transport');
Assert::same(1,$transport->calls,'credential refusal made no call');
$credentialId=$credentialStore->save($scope,$key)->value()['provider_credential_id'];
$quotaTransport=new FixtureModelTransport(static fn($r)=>new ModelResponse(429,'{"error":{"code":"insufficient_quota","message":"DO-NOT-LEAK"}}'));
$quota=new ModelExecutor($db,$clock,$gateway,$credentialStore,$quotaTransport,$contextService,$modelArtifacts);
$r=$quota->execute([...$command,'idempotency_key'=>'model-quota','correlation_id'=>Ids::new()],$request,$credentialId);
Assert::same('MODEL_QUOTA_EXHAUSTED',$r['reason_code'],'quota is a terminal governed refusal');
Assert::same(1,$quotaTransport->calls,'no quota retry');
Assert::false(str_contains(json_encode($r),'DO-NOT-LEAK'),'quota raw message never returned');
$revokingTransport=new FixtureModelTransport(static function($r)use($db,$model,$wire,$sample){$db->run("UPDATE governed_tools SET status='SUSPENDED' WHERE governed_tool_id=?",[$model['governed_tool_id']]);return new ModelResponse(200,$wire($sample));});
$revoking=new ModelExecutor($db,$clock,$gateway,$credentialStore,$revokingTransport,$contextService,$modelArtifacts);
$r=$revoking->execute([...$command,'idempotency_key'=>'model-revoked-during-call','correlation_id'=>Ids::new()],$request,$credentialId);
Assert::same('MODEL_REFUSED',$r['kind'],'authority change during provider callback withholds candidate');
Assert::false(isset($r['candidate']),'no candidate escapes post-dispatch refusal');
$db->run("UPDATE governed_tools SET status='ACTIVE' WHERE governed_tool_id=?",[$model['governed_tool_id']]);
$r=$executor->execute([...$command,'idempotency_key'=>'model-budget','correlation_id'=>Ids::new()],$request,$credentialId);
Assert::same('MODEL_MISSION_BUDGET_EXHAUSTED',$r['reason_code'],'all attempted terminal outcomes consume bounded mission budget');
Assert::same(1,$transport->calls,'budget refusal invokes no transport');
Assert::same(4,(int)$db->scalar('SELECT COUNT(*) FROM provider_model_attempts'),'attempt reservations are bounded');
Assert::same(0,(int)$db->scalar('SELECT COUNT(*) FROM released_briefings'),'model path cannot release P01');
